// Headers of generated files (10 §15.1, "Drift is caught four ways", 2: hand edits).
//
// Every file a generator writes into src/shared/gen/, crates/schema/src/ or crates/sim/src/gen/ starts
// with two comment lines:
//
//   // @generated by scripts/schema-gen.ts from schema/. Do not edit: change the source and run `npm run gen`.
//   // schema-hash: <64 hex> content-hash: <64 hex>
//
// The content hash is the SHA-256 of everything after the second line's newline. scripts/check-arch.ts
// recomputes it and refuses a mismatch, so a hand edit fails the check. The schema hash is optional
// (data-stage outputs carry none). `#` replaces `//` in TOML.
import { sha256Hex } from './hash.ts';

/** The directories only generators write (10 §2.2), relative to game/. */
export const GENERATED_DIRS = ['src/shared/gen', 'crates/schema/src', 'crates/sim/src/gen'] as const;

export type Generator = 'scripts/schema-gen.ts' | 'scripts/data-stage.ts';
export type CommentStyle = '//' | '#';

export interface HeaderSpec {
  generator: Generator;
  /** What the file is generated from, e.g. `schema/` or `design/spec/data`. */
  source: string;
  /** The command that regenerates it, e.g. `npm run gen`. */
  command: string;
  schemaHash?: string;
  comment?: CommentStyle;
}

export interface HeaderInfo {
  generator: string;
  source: string;
  schemaHash: string | null;
  contentHash: string;
  /** The body the content hash covers. */
  body: string;
}

const LINE1 = /^(\/\/|#) @generated by (scripts\/[A-Za-z0-9_./-]+\.ts) from (\S+?)\. Do not edit: .+$/;
const LINE2 = /^(\/\/|#) (?:schema-hash: ([0-9a-f]{64}) )?content-hash: ([0-9a-f]{64})$/;

/** Prepends the two header lines to `body`. */
export function withHeader(spec: HeaderSpec, body: string): string {
  const c = spec.comment ?? '//';
  const l1 = `${c} @generated by ${spec.generator} from ${spec.source}. Do not edit: change the source and run \`${spec.command}\`.`;
  const schema = spec.schemaHash === undefined ? '' : `schema-hash: ${spec.schemaHash} `;
  const l2 = `${c} ${schema}content-hash: ${sha256Hex(body)}`;
  return `${l1}\n${l2}\n${body}`;
}

/** Parses a generated file's header; null when the file has none. */
export function parseHeader(text: string): HeaderInfo | null {
  const nl1 = text.indexOf('\n');
  const nl2 = nl1 < 0 ? -1 : text.indexOf('\n', nl1 + 1);
  if (nl2 < 0) return null;
  const m1 = LINE1.exec(text.slice(0, nl1));
  const m2 = LINE2.exec(text.slice(nl1 + 1, nl2));
  if (!m1 || !m2 || m1[1] !== m2[1]) return null;
  return {
    generator: m1[2] ?? '',
    source: m1[3] ?? '',
    schemaHash: m2[2] ?? null,
    contentHash: m2[3] ?? '',
    body: text.slice(nl2 + 1),
  };
}

/** Why a generated file fails its header check, or null when it passes. */
export function headerProblem(text: string): string | null {
  const h = parseHeader(text);
  if (!h) return 'missing or malformed `@generated` header';
  if (h.generator !== 'scripts/schema-gen.ts' && h.generator !== 'scripts/data-stage.ts') {
    return `unknown generator ${h.generator}`;
  }
  const actual = sha256Hex(h.body);
  if (actual !== h.contentHash) {
    return `content hash mismatch (header ${h.contentHash.slice(0, 12)}…, file ${actual.slice(0, 12)}…): edited by hand? Regenerate it`;
  }
  return null;
}
